```cpp
#include "3mm.h"
#include <string.h>
#include <ap_int.h>

// ------------------------------------------------------------------
// Self-contained wide-bus definitions (replaces missing mc.h)
// ------------------------------------------------------------------
#ifndef LARGE_BUS
#define LARGE_BUS 512
#endif
typedef ap_uint<LARGE_BUS> MARS_WIDE_BUS_TYPE;

// Read 'num' elements of type T starting at element-offset 'offset' from a
// wide-bus port into a local buffer.
template <typename T, int W>
static void memcpy_wide_bus_read_float(T *local, ap_uint<W> *bus,
                                       long offset, int num)
{
  const int ELEMS = W / (8 * sizeof(T));
  RD_OUTER: for (int idx = 0; idx < num; ) {
    long elem = offset + idx;
    long word = elem / ELEMS;
    int  lane = elem % ELEMS;
    ap_uint<W> data = bus[word];
    RD_INNER: for (; lane < ELEMS && idx < num; lane++, idx++) {
#pragma HLS PIPELINE II=1
      ap_uint<8 * sizeof(T)> raw =
          data.range((lane + 1) * 8 * sizeof(T) - 1, lane * 8 * sizeof(T));
      union { ap_uint<8 * sizeof(T)> u; T v; } cvt;
      cvt.u = raw;
      local[idx] = cvt.v;
    }
  }
}

// Write 'num' elements of type T from a local buffer into a wide-bus port
// starting at element-offset 'offset'.
template <typename T, int W>
static void memcpy_wide_bus_write_float(ap_uint<W> *bus, T *local,
                                        long offset, int num)
{
  const int ELEMS = W / (8 * sizeof(T));
  WR_OUTER: for (int idx = 0; idx < num; ) {
    long elem = offset + idx;
    long word = elem / ELEMS;
    int  lane = elem % ELEMS;
    ap_uint<W> data = bus[word];
    WR_INNER: for (; lane < ELEMS && idx < num; lane++, idx++) {
#pragma HLS PIPELINE II=1
      union { ap_uint<8 * sizeof(T)> u; T v; } cvt;
      cvt.v = local[idx];
      data.range((lane + 1) * 8 * sizeof(T) - 1, lane * 8 * sizeof(T)) = cvt.u;
    }
    bus[word] = data;
  }
}

